import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.DncwoWA8.js";const u=JSON.parse('{"title":"Productivity","description":"","frontmatter":{"title":"Productivity"},"headers":[],"relativePath":"groups/productivity.md","filePath":"groups/productivity.md"}'),r={name:"groups/productivity.md"};function s(l,e,n,c,h,d){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="productivity" tabindex="-1">Productivity <a class="header-anchor" href="#productivity" aria-label="Permalink to &quot;Productivity&quot;">​</a></h1><p>Research questions, shape initiatives, specify behavior, plan tasks, and learn from results.</p><p>Choose by the task you have now. These are the collection&#39;s groups, including external recommendations. They are not a mandatory delivery pipeline.</p><h2 id="initiative" tabindex="-1"><a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> <a class="header-anchor" href="#initiative" aria-label="Permalink to &quot;[`initiative`](/skills/initiative)&quot;">​</a></h2><p>Turn an idea or research into an agreed brief covering the problem, outcomes, scope, constraints, and success measures.</p><p><strong>Choose it when:</strong> An idea needs an agreed problem, outcome, scope, constraints, and success measures before solution work.</p><h2 id="research" tabindex="-1"><a href="/projects/ai-skills/skills/research.html"><code>research</code></a> <a class="header-anchor" href="#research" aria-label="Permalink to &quot;[`research`](/skills/research)&quot;">​</a></h2><p>Research a question, compare alternatives, or investigate feasibility; report verified evidence, uncertainty, and limits.</p><p><strong>Choose it when:</strong> A decision depends on facts, alternatives, feasibility, or evidence that you do not yet have.</p><h2 id="specify" tabindex="-1"><a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> <a class="header-anchor" href="#specify" aria-label="Permalink to &quot;[`specify`](/skills/specify)&quot;">​</a></h2><p>Turn agreed decisions into a compact specification with observable behavior, acceptance criteria, constraints, and test boundaries.</p><p><strong>Choose it when:</strong> The direction is agreed but observable behavior, acceptance criteria, constraints, or test boundaries remain unclear.</p><h2 id="plan-tasks" tabindex="-1"><a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> <a class="header-anchor" href="#plan-tasks" aria-label="Permalink to &quot;[`plan-tasks`](/skills/plan-tasks)&quot;">​</a></h2><p>Divide an agreed specification or clear scope into bounded, verifiable tasks with explicit dependencies and completion evidence.</p><p><strong>Choose it when:</strong> The scope or specification is clear enough to divide into bounded pieces of work.</p><h2 id="retro" tabindex="-1"><a href="/projects/ai-skills/skills/retro.html"><code>retro</code></a> <a class="header-anchor" href="#retro" aria-label="Permalink to &quot;[`retro`](/skills/retro)&quot;">​</a></h2><p>Review a bounded work period for evidence-backed process improvements, including workflow, instructions, tools, and handoffs.</p><p><strong>Choose it when:</strong> A bounded completed work period has enough evidence to review what helped, failed, or should change.</p><h2 id="grill-me" tabindex="-1"><a href="/projects/ai-skills/skills/grill-me.html"><code>grill-me</code></a> <a class="header-anchor" href="#grill-me" aria-label="Permalink to &quot;[`grill-me`](/skills/grill-me)&quot;">​</a></h2><p>A relentless interview to sharpen a plan or design.</p><p><strong>Choose it when:</strong> You want to explicitly start the grilling interview through a small local composition.</p><h2 id="grilling" tabindex="-1"><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> <a class="header-anchor" href="#grilling" aria-label="Permalink to &quot;[`grilling`](/skills/grilling)&quot;">​</a></h2><p>Stress-test a plan or decision through an explicit interview.</p><p><strong>Choose it when:</strong> A plan or design needs a focused interview rather than another polished document built on assumptions.</p><h2 id="wait-what" tabindex="-1"><a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> <a class="header-anchor" href="#wait-what" aria-label="Permalink to &quot;[`wait-what`](/skills/wait-what)&quot;">​</a></h2><p>Explain the current proposal again with simpler language and missing context.</p><p><strong>Choose it when:</strong> The last answer is hard to understand or omits context needed to follow the current proposal.</p><h2 id="try-a-workflow" tabindex="-1">Try a workflow <a class="header-anchor" href="#try-a-workflow" aria-label="Permalink to &quot;Try a workflow&quot;">​</a></h2><ul><li><a href="/projects/ai-skills/workflows/research-a-decision.html">Research before choosing an approach</a> — Missing facts could change a technical or product decision.</li><li><a href="/projects/ai-skills/workflows/shape-an-initiative.html">Turn an idea into an outcome-level brief</a> — The problem and success measures are less clear than the proposed solution.</li><li><a href="/projects/ai-skills/workflows/specify-observable-behavior.html">Agree on behavior before task execution</a> — An agreed direction still leaves observable behavior or acceptance criteria open.</li><li><a href="/projects/ai-skills/workflows/plan-bounded-tasks.html">Divide agreed scope into verifiable tasks</a> — The work is understood but too large to execute as one unbounded change.</li><li><a href="/projects/ai-skills/workflows/challenge-a-design.html">Challenge a plan without implementing it</a> — A confident proposal may conceal unresolved assumptions or decisions.</li><li><a href="/projects/ai-skills/workflows/learn-from-completed-work.html">Turn a completed issue into a small improvement</a> — A bounded work period has enough evidence to examine the process.</li><li><a href="/projects/ai-skills/workflows/re-pitch-an-explanation.html">Ask for a clearer explanation</a> — The last proposal or explanation is unclear, lacks context, or does not use the project&#39;s shared vocabulary.</li></ul>',29)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
